import { decrypt, encrypt, type EncryptedBlob } from "./crypto.js";

// Generic version of what changeMasterPassword already does inline for every entry and for the
// sharing private key: decrypt under the OLD key, re-encrypt the exact same plaintext under the NEW
// key. A fresh IV happens automatically, since encrypt() always generates one internally.
export function reencryptBlob(oldKey: Buffer, newKey: Buffer, blob: EncryptedBlob): EncryptedBlob {
  const plaintext = decrypt(oldKey, blob); // throws DECRYPTION_FAILED on a wrong key or tampered blob
  return encrypt(newKey, plaintext);
}

