// solution, following the exact shape of addEntry/claimEntryOp
async archiveVault(sessionId: string): Promise<void> {
  const session = this.requireSession(sessionId);
  const record = this.requireVault(session.ownerId);

  this.claimEntryOp(record); // reuse the existing claim: excludes (and is excluded by) a rotation
  try {
    await this.commit(record, {
      salt: record.salt,
      canary: record.canary,
      entries: [...record.entries.values()],
      sharingPublicKey: record.sharingPublicKey,
      wrappedPrivateKey: record.wrappedPrivateKey,
      // archived: true, // would need VaultRecord/PersistedVault/commit() extended with this field
    });
    record.archived = true; // only applied after the store confirms it
  } finally {
    record.pendingEntryOps--; // released whether the commit succeeded or threw
  }
}

