// solution -- a token-bucket middleware, inserted right after the auth check in createApp
function rateLimiter(capacity: number, refillPerMs: number) {
  const buckets = new Map<string, { tokens: number; lastRefillAt: number }>();
  return (req: Request, res: Response, next: NextFunction) => {
    const key = req.get("authorization") ?? "anonymous"; // per-API-key bucket
    const now = Date.now();
    const bucket = buckets.get(key) ?? { tokens: capacity, lastRefillAt: now };
    const elapsed = now - bucket.lastRefillAt;
    bucket.tokens = Math.min(capacity, bucket.tokens + elapsed * refillPerMs);
    bucket.lastRefillAt = now;
    if (bucket.tokens < 1) {
      buckets.set(key, bucket);
      res.status(429).json({ error: { code: "RATE_LIMITED", message: "too many requests" } });
      return;
    }
    bucket.tokens -= 1;
    buckets.set(key, bucket);
    next();
  };
}

